Add helper functions for making API requests and formatting responses: async fn make_nws_request<T: DeserializeOwned>(url: &str) -> Result<T> { let client = reqwest::Client::new(); let rsp = client .get(url) .header(reqwest::header::USER_AGENT, USER_AGENT) .header(reqwest::header::ACCEPT, "application/geo+json") .send() .await? .error_for_status()?; Ok(rsp.json::<T>().await?) } fn format_alert(feature: &AlertFeature) -> String { let props = &feature.properties; format!( "Event: {}
Area: {}
Severity: {}
Description: {}
Instructions: {}", props.event.as_deref().unwrap_or("Unknown"), props.area_desc.as_deref().unwrap_or("Unknown"), props.severity.as_deref().unwrap_or("Unknown"), props .description .as_deref() .unwrap_or("No description available"), props .instruction .as_deref() .unwrap_or("No specific instructions provided") ) } fn format_period(period: &ForecastPeriod) -> String { format!( "{}:
Temperature: {}°{}
Wind: {} {}
Forecast: {}", period.name, period.temperature, period.temperature_unit, period.wind_speed, period.wind_direction, period.detailed_forecast ) }

interface ReadResourceResultResponse { jsonrpc: “2.0”; id: RequestId; result: InputRequiredResult | ReadResourceResult;} A successful response from the server for a resources/read request. Example: Read resource result response { “jsonrpc”: “2.0”, “id”: “read-resource-example”, “result”: { “resultType”: “complete”, “contents”: [ { “uri”: “file:///project/src/main.rs”, “mimeType”: “text/x-rust”, “text”: “fn main() {
 println!(\“Hello world!\”);
}” } ] }} Example: Read resource result response with TTL { “jsonrpc”: “2.0”, “id”: “read-resource-with-ttl-example”, “result”: { “resultType”: “complete”, “contents”: [ { “uri”: “file:///project/src/main.rs”, “mimeType”: “text/x-rust”, “text”: “fn main() {
 println!(\“Hello world!\”);
}” } ], “ttlMs”: 60000, “cacheScope”: “private” }} jsonrpc: “2.0” Inherited from JSONRPCResultResponse.jsonrpc id: RequestId Inherited from JSONRPCResultResponse.id result: InputRequiredResult | ReadResourceResult Overrides JSONRPCResultResponse.result
